<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Donation receipt {{ $donation->receipt_number }}</title><style>body{font-family:Arial,sans-serif;color:#1d3026;background:#f5f7f5;margin:0;padding:30px}.receipt{max-width:760px;margin:20px auto;background:#fff;border:1px solid #dce5dd;border-radius:16px;padding:38px}.top{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;border-bottom:2px solid #0b7542;padding-bottom:22px}.muted{color:#68756c}.amount{font-size:2rem;font-weight:800;margin:26px 0}.line{padding:12px 0;border-bottom:1px solid #e8ece8}.actions{margin:20px auto;max-width:760px}@media print{body{background:#fff;padding:0}.receipt{border:0;margin:0;max-width:none}.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button> <a href="{{ route('admin.operations.index','donations') }}">Back to donations</a></div><article class="receipt"><div class="top"><div><h1>Muhamadi R Charity Foundation Uganda</h1><p class="muted">Donation receipt</p></div><div><strong>{{ $donation->receipt_number }}</strong><p class="muted">{{ $donation->donation_date }}</p></div></div><div class="amount">{{ $donation->currency }} {{ number_format((float)$donation->amount, 2) }}</div><p>This receipt records a donation marked as paid in the foundation's administration system.</p><div class="line"><strong>Received from</strong><br>{{ $donation->donor_name }}</div><div class="line"><strong>Payment method</strong><br>{{ $donation->payment_method }}</div><div class="line"><strong>Payment reference</strong><br>{{ $donation->reference ?: 'Not recorded' }}</div><div class="line"><strong>Status</strong><br>Confirmed paid</div><p class="muted" style="margin-top:28px">Please retain this receipt for your records. It reflects the payment status entered by an authorised administrator.</p></article></body></html>
